<script lang="ts">
 import {createEventDispatcher,onDestroy} from 'svelte';
 export let request:(path:string,init?:RequestInit)=>Promise<Response>;export let companyId:string;export let availableTypes:string[]=[];
 const dispatch=createEventDispatcher(),abort=new AbortController();let expanded=false,loading=false,error='',items:any[]=[];
 async function browse(){expanded=!expanded;if(!expanded)return;loading=true;error='';items=[];
  const base='/api/v1/companies/'+encodeURIComponent(companyId);
  const jobs=[...(availableTypes.includes('resource.file')||availableTypes.includes('resource.document')?[{path:base+'/drive?recent=1',domain:'drive'}]:[]),...(availableTypes.includes('resource.sheet')?[{path:base+'/sheets',domain:'sheet'}]:[]),...(availableTypes.includes('resource.email')?[{path:base+'/email-studio',domain:'email'}]:[])];
  for(const job of jobs){try{const response=await request(job.path,{signal:abort.signal,cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok||!response.headers.get('Content-Type')?.includes('application/json'))throw Error('Resource list unavailable');const body=await response.json();const rows=job.domain==='drive'?body.data:job.domain==='email'?body.drafts:body;if(!Array.isArray(rows))throw Error('Invalid resource list');if(abort.signal.aborted)return;for(const row of rows){if(job.domain==='email'){if(row.companyId!==companyId||typeof row.id!=='string')continue;const detail=await request(base+'/email-studio/'+encodeURIComponent(row.id),{signal:abort.signal,cache:'no-store',headers:{Accept:'application/json'}});if(!detail.ok)continue;const record=await detail.json();if(record.id!==row.id||record.companyId!==companyId||typeof record.document?.subject!=='string')continue;items=[...items,{id:row.id,title:record.document.subject||'Untitled email',kind:'email',type:'resource.email'}];continue;}const kind=job.domain==='sheet'?'sheet':row.kind,type=({file:'resource.file',knowledge:'resource.document',task:'resource.tasks',project:'resource.project',sheet:'resource.sheet'} as Record<string,string>)[kind];if(typeof row.id==='string'&&type&&availableTypes.includes(type))items=[...items,{id:row.id,title:row.title||row.name||'Untitled resource',kind,type}];}}
   catch{if(!abort.signal.aborted)error='Some resource lists could not be verified.';}}
  if(!abort.signal.aborted)loading=false;
 }
 function open(item:any){dispatch('open',{version:'starli.panel.v1',action:'open',type:item.type,ref:{scope:'company',ownerId:companyId,kind:item.kind,id:item.id},mode:'docked'});}
 onDestroy(()=>abort.abort());
</script>
<div class="my-3 text-sm"><button type="button" class="rounded-xl border border-gray-200 px-3 py-2 dark:border-gray-700" aria-expanded={expanded} on:click={browse}>{expanded?'Close resource list':'Open company resource'}</button>
{#if expanded}<div class="my-3 rounded-xl border border-gray-200 p-3 dark:border-gray-800">{#if loading}<p role="status">Loading authorized resources…</p>{:else}<ul class="divide-y divide-gray-100 dark:divide-gray-800">{#each items as item(item.type+item.id)}<li><button type="button" class="flex w-full items-center justify-between gap-3 py-3 text-left" on:click={()=>open(item)}><span>{item.title}</span><small class="text-gray-500">{item.kind}</small></button></li>{:else}<li class="py-3 text-gray-500">No available resources in the verified lists.</li>{/each}</ul>{/if}{#if error}<p role="status" class="mt-2 text-gray-500">{error}</p>{/if}</div>{/if}</div>
